def _convert_openai_clip(state_dict, model, prefix='visual.'):
    model_has_attn_pool = isinstance(model.head, (RotAttentionPool2d, AttentionPool2d))
    import re

    def _stage_sub(m):
        stage_idx = int(m.group(1)) - 1
        layer_idx, layer_type, layer_id = (int(m.group(2)), m.group(3), int(m.group(4)))
        prefix_str = 'stages.{0}.{1}.'.format(stage_idx, layer_idx)
        id_map = {1: 'conv1_1x1.', 2: 'conv2_kxk.', 3: 'conv3_1x1.'}
        suffix_str = id_map[layer_id] + layer_type
        return prefix_str + suffix_str

    def _down_sub(m):
        stage_idx = int(m.group(1)) - 1
        layer_idx, layer_id = (int(m.group(2)), int(m.group(3)))
        return 'stages.{0}.{1}.shortcut.'.format(stage_idx, layer_idx) + ('conv.conv' if layer_id == 0 else 'conv.bn')
    out_dict = {}
    for k, v in state_dict.items():
        if not k.startswith(prefix):
            continue
        k = re.sub('{0}conv([0-9])'.format(prefix), 'stem.conv\\1.conv', k)
        k = re.sub('{0}bn([0-9])'.format(prefix), 'stem.conv\\1.bn', k)
        k = re.sub('{0}layer([0-9])\\.([0-9]+)\\.([a-z]+)([0-9])'.format(prefix), _stage_sub, k)
        k = re.sub('{0}layer([0-9])\\.([0-9]+)\\.downsample\\.([0-9])'.format(prefix), _down_sub, k)
        if k.startswith('{0}attnpool'.format(prefix)):
            if not model_has_attn_pool:
                continue
            k = k.replace(prefix + 'attnpool', 'head')
            k = k.replace('positional_embedding', 'pos_embed')
            k = k.replace('q_proj', 'q')
            k = k.replace('k_proj', 'k')
            k = k.replace('v_proj', 'v')
            k = k.replace('c_proj', 'proj')
        out_dict[k] = v
    return out_dict

def checkpoint_filter_fn(state_dict, model):
    if 'visual.conv1.weight' in state_dict:
        state_dict = _convert_openai_clip(state_dict, model)
    return state_dict

def _create_byobnet(variant, pretrained=False, **kwargs):
    """Create a ByobNet model.

    Args:
        variant: Model variant name.
        pretrained: Load pretrained weights.
        **kwargs: Additional model arguments.

    Returns:
        ByobNet model instance.
    """
    return build_model_with_cfg(ByobNet, variant, pretrained, model_cfg=model_cfgs[variant], pretrained_filter_fn=checkpoint_filter_fn, feature_cfg=dict(flatten_sequential=True), **kwargs)

@register_model
def repvgg_a2(pretrained=False, **kwargs):
    """ RepVGG-A2
    `Making VGG-style ConvNets Great Again` - https://arxiv.org/abs/2101.03697
    """
    return _create_byobnet('repvgg_a2', pretrained=pretrained, **kwargs)
